cpu_switch:
  sd ra, (PCB_RA)(x13)     /* saves ra, sp, s0-s11 */
  sd sp, (PCB_SP)(x13)
  /* ... no csrr sspcs / sd to PCB */
  /* ... no ld from PCB / csrw sspcs on restore */

struct pcb {
  uint64_t pcb_ra, pcb_sp, pcb_gp, pcb_tp;
  uint64_t pcb_s[12];
  uint64_t pcb_x[32][2]; /* FPU saved */
  uint64_t pcb_fcsr;     /* FP CSR saved */
  /* no pcb_sspcs, no pcb_sspcs_present */
};

struct trapframe {
  uint64_t tf_ra, tf_sp, tf_gp, tf_tp;
  uint64_t tf_t[7], tf_s[12], tf_a[8];
  uint64_t tf_sepc, tf_sstatus, tf_stval, tf_scause;
  /* no tf_sspcs */
};

ASSYM(PCB_RA, offsetof(struct pcb, pcb_ra));
ASSYM(PCB_SP, offsetof(struct pcb, pcb_sp));
/* ... no PCB_SSPCS */
ASSYM(TF_SEPC, offsetof(struct trapframe, tf_sepc));
/* ... no TF_SSPCS */

